171.         pub closed spec fn filter_r(shared_guard: Multiset<(int, T)>, r: int) -> Multiset<(int, T)> {
172.             shared_guard.filter(|val: (int, T)| val.0 == r)
173.         }
174. 
175.         #[invariant]
176.         pub fn shared_counts_agree(&self) -> bool {
177.             forall |r| 0 <= r < self.rc_width ==>
178.                 #[trigger] self.ref_counts.index(r) ==
179.                     self.shared_pending.count(r) as int +
180.                         Self::filter_r(self.shared_guard, r).len() as int
181.         }
